        "onboardingV2.review.appStore": "sull'App Store",
        "onboardingV2.review.author": "Léa, 24",
        "onboardingV2.review.quote": "« Prima passavo 7 ore al giorno sul telefono. Ora solo 40 minuti con Sophia, e mi sento più intelligente ogni settimana. »",
