        "onboardingV2.review.t2.author": "Yanis, 27",
        "onboardingV2.review.t2.quote": "10 minuti la mattina in metro e la sera ho qualcosa da raccontare. Davvero dipendente.",
        "onboardingV2.review.t3.author": "Inès, 19",
        "onboardingV2.review.t3.quote": "Ho sempre odiato «studiare», ma qui resta da solo. La mia memoria mi sorprende.",
        "onboardingV2.review.t4.author": "Thomas, 31",
        "onboardingV2.review.t4.quote": "Sostituisco gli scroll senza fine con un corso. In un mese, chi mi sta intorno ha notato la differenza.",
        "onboardingV2.review.t5.author": "Sarah, 26",
        "onboardingV2.review.t5.quote": "Finalmente un'app che mi fa sentire di avanzare, non di perdere tempo. La apro ogni giorno.",
