        "onboardingV2.review.appStore": "w App Store",
        "onboardingV2.review.quote": "„Kiedyś spędzałam 7 godzin dziennie na telefonie. Teraz tylko 40 minut z Sophią i z każdym tygodniem czuję się mądrzejsza”.",
        "onboardingV2.review.author": "Lea, 24",
        "onboardingV2.review.t1.quote": "Ponieważ rzadziej przewijam i korzystam z Sophii, mam wrażenie, że faktycznie pamiętam o wiele więcej.",
        "onboardingV2.review.t1.author": "Kamil, 22",
        "onboardingV2.review.t2.quote": "10 minut w pociągu rano i wieczorem mam o czym rozmawiać. Szczerze mówiąc, uzależniony.",
        "onboardingV2.review.t2.author": "Janis, 27",
        "onboardingV2.review.t3.quote": "Zawsze nienawidziłem „uczyć się”, ale to po prostu zostało. Pamięć mnie ciągle zaskakuje.",
        "onboardingV2.review.t3.author": "Ines, 19",
        "onboardingV2.review.t4.quote": "Zamieniam niekończące się przewijanie na lekcję. Po miesiącu ludzie wokół mnie zauważyli różnicę.",
        "onboardingV2.review.t4.author": "Tomasz, 31",
        "onboardingV2.review.t5.quote": "Wreszcie aplikacja, która sprawia, że ​​czuję, że idę do przodu, a nie marnuję czas. Otwieram codziennie.",
        "onboardingV2.review.t5.author": "Sara, 26",
        "onboardingV2.review.t6.quote": "Quizy z odstępami są magiczne: pamiętam rzeczy, których nauczyłem się kilka tygodni temu, nawet nie próbując.",
        "onboardingV2.review.t6.author": "Malika, 23",
