        "onboardingV2.exams.title": "Βελτίωσαν τους βαθμούς τους",
        "onboardingV2.exams.quote1": "«Χάρη στη Σοφία, ο μέσος όρος της ιστορίας μου ανέβηκε 3 βαθμούς αυτή τη σεζόν».",
        "onboardingV2.exams.author1": "Θωμάς, μαθητής",
        "onboardingV2.exams.quote2": "«Αναθεωρώ 10 λεπτά την ημέρα και οι βαθμοί μου πραγματικά απογειώθηκαν».",
        "onboardingV2.exams.author2": "Inès, τελειόφοιτος",
        "onboardingV2.exams.quote3": "«Τα κουίζ με βοήθησαν να θυμάμαι τα απαραίτητα πριν από τις εξετάσεις μου».",
        "onboardingV2.exams.author3": "Camille, πανεπιστήμιο",
        "onboardingV2.exams.quote4": "\"Ιδανικό για αναθεώρηση εν κινήσει. Οι δάσκαλοί μου παρατήρησαν τη διαφορά.\"",
