        "onboardingV2.exams.title": "Zlepšili si známky",
        "onboardingV2.exams.quote1": "\"Díky Sophii se můj historický průměr v tomto období zvýšil o 3 body.\"",
        "onboardingV2.exams.author1": "Tomáš, student",
        "onboardingV2.exams.quote2": "\"Opravuji 10 minut denně a moje známky opravdu šly.\"",
        "onboardingV2.exams.author2": "Inès, poslední ročník",
        "onboardingV2.exams.quote3": "\"Kvízy mi pomohly zapamatovat si to podstatné před zkouškami.\"",
        "onboardingV2.exams.author3": "Camille, univerzita",
        "onboardingV2.exams.quote4": "\"Ideální pro opakování na cestách. Moji učitelé si toho rozdílu všimli.\"",
