        "onboardingV2.weeks.subtitle": "Toto je váš rok. Červená: čas strávený na obrazovce.",
        "onboardingV2.weeks.caption": "Představte si, co byste se mohli naučit za zlomek tohoto času.",
        "onboardingV2.review.title": "Zde je názor našich uživatelů",
        "onboardingV2.review.appStore": "na App Store",
        "onboardingV2.review.quote": "\"Dříve jsem trávil 7 hodin denně na svém telefonu. Teď jen 40 minut se Sophií a každý týden se cítím chytřejší.\"",
        "onboardingV2.review.author": "Léa, 24",
        "onboardingV2.review.t1.quote": "Vzhledem k tomu, že méně roluji a používám Sophii, mám pocit, že si ve skutečnosti pamatuji mnohem více.",
        "onboardingV2.review.t1.author": "Kamila, 22",
        "onboardingV2.review.t2.quote": "10 minut ve vlaku ráno a večer si mám o čem povídat. Upřímně zahnutý.",
        "onboardingV2.review.t2.author": "Yanis, 27",
        "onboardingV2.review.t3.quote": "Vždycky jsem nenáviděl „studování“, ale tohle prostě zůstane. Moje paměť mě stále překvapuje.",
        "onboardingV2.review.t3.author": "Ines, 19",
        "onboardingV2.review.t4.quote": "Své nekonečné rolování vyměňuji za lekci. Za měsíc si lidé v mém okolí všimli rozdílu.",
        "onboardingV2.review.t4.author": "Tomáš, 31",
        "onboardingV2.review.t5.quote": "Konečně aplikace, díky které mám pocit, že se posouvám vpřed a neztrácím čas. Otevírám každý den.",
        "onboardingV2.review.t5.author": "Sarah, 26",
        "onboardingV2.review.t6.quote": "Rozložené kvízy jsou kouzlo: Pamatuji si věci, které jsem se naučil před týdny, aniž bych se o to snažil.",
        "onboardingV2.review.t6.author": "Malik, 23",
